import { gsap } from 'gsap';
import { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, Vector3, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  const timelines = [];
  const cleanups = [];
  const materials = [];
  const geometries = [];
  const textures = [];

  // ============================================================================
  // 1. BACKDROP PLANE (7 x 6 units at z=-3, vertical gradient)
  // ============================================================================
  const backdropGeo = new PlaneGeometry(7, 6);
  geometries.push(backdropGeo);

  const backdropMat = new MeshBasicNodeMaterial();

  // TSL gradient: dark bottom (#0b0b10) → mid (#101017) → dark top (#16161d)
  const uvNode = uv();
  const yNorm = uvNode.y; // 0 = top, 1 = bottom in default UV mapping

  const col0 = vec3(0.0627, 0.0627, 0.0902); // #101017 (mid)
  const col1 = vec3(0.0431, 0.0431, 0.0627); // #0b0b10 (darker)
  const col2 = vec3(0.0862, 0.0862, 0.1137); // #16161d (dark)

  // Invert for proper top-to-bottom: top is col2, bottom is col1, mid is col0
  const gradLower = mix(col1, col0, smoothstep(0, 0.7, yNorm));
  const gradFinal = mix(gradLower, col2, smoothstep(0.7, 1, yNorm));

  backdropMat.colorNode = gradFinal;

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -3;
  backdropMesh.renderOrder = 0;
  group.add(backdropMesh);
  materials.push(backdropMat);

  // ============================================================================
  // 2. TORUS KNOT (brushed metal hero with anisotropy)
  // ============================================================================
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  knotGeo.center();
  geometries.push(knotGeo);

  const knotMat = new MeshStandardNodeMaterial();

  // Base color: #14141a (surface) - slightly lighter than background
  knotMat.colorNode = uniform(new Color(0x14141a));

  // Roughness with texture map loaded asynchronously
  let roughnessNode = uniform(0.55);
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((roughTexture) => {
      roughTexture.anisotropy = 16;
      // Roughness: base 0.55 + map variation (center 0.9 multiplier)
      roughnessNode = mix(
        uniform(0.55),
        texture(roughTexture).r.mul(1.0),
        uniform(0.5)
      );
      knotMat.roughnessNode = roughnessNode;
      knotMat.needsUpdate = true;
      textures.push(roughTexture);
    });
  }
  knotMat.roughnessNode = roughnessNode;

  // Strong PBR for brushed metal effect
  knotMat.metalnessNode = uniform(0.62);   // Increased metalness for stronger metal response
  knotMat.clearcoatNode = uniform(0.22);
  knotMat.clearcoatRoughnessNode = uniform(0.35);
  knotMat.anisotropyNode = uniform(0.95);  // Max anisotropy for visible streaks
  knotMat.anisotropyRotation = Math.PI / 2;

  // Procedural scratch normal map for imperfection
  const scratchCanvas = document.createElement('canvas');
  scratchCanvas.width = 512;
  scratchCanvas.height = 512;
  const scratchCtx = scratchCanvas.getContext('2d');

  // Base: neutral normal blue
  scratchCtx.fillStyle = '#8080ff';
  scratchCtx.fillRect(0, 0, scratchCanvas.width, scratchCanvas.height);

  // Fine directional scratch streaks aligned to tube direction
  scratchCtx.globalAlpha = 0.3;
  for (let i = 0; i < 5000; i++) {
    const x = Math.random() * scratchCanvas.width;
    const y = Math.random() * scratchCanvas.height;
    const angle = (Math.random() - 0.5) * 0.2; // mostly horizontal
    const len = Math.random() * 20 + 5;

    scratchCtx.strokeStyle = `rgb(128, 128, ${130 + Math.random() * 20})`;
    scratchCtx.lineWidth = Math.random() * 0.8 + 0.2;
    scratchCtx.beginPath();
    scratchCtx.moveTo(x, y);
    scratchCtx.lineTo(x + Math.cos(angle) * len, y + Math.sin(angle) * len);
    scratchCtx.stroke();
  }
  scratchCtx.globalAlpha = 1;

  const scratchTexture = new ctx.THREE.CanvasTexture(scratchCanvas);
  scratchTexture.needsUpdate = true;

  knotMat.normalMapNode = texture(scratchTexture);
  knotMat.normalScale = new Vector3(0.18, 0.18, 0.18);
  textures.push(scratchTexture);

  const knotMesh = new Mesh(knotGeo, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  knotMesh.castShadow = true;
  knotMesh.receiveShadow = true;
  group.add(knotMesh);
  materials.push(knotMat);

  // ============================================================================
  // 3. PEDESTAL (cylindrical base, fully visible)
  // ============================================================================
  const pedGeo = new CylinderGeometry(1.1, 1.1, 0.5, 128, 8, false);
  geometries.push(pedGeo);

  const pedMat = new MeshStandardNodeMaterial();
  pedMat.colorNode = uniform(new Color(0x14141a));
  pedMat.roughnessNode = uniform(0.65);
  pedMat.metalnessNode = uniform(0.4);

  const pedMesh = new Mesh(pedGeo, pedMat);
  pedMesh.position.y = -0.35;
  pedMesh.castShadow = true;
  pedMesh.receiveShadow = true;
  group.add(pedMesh);
  materials.push(pedMat);

  // Chamfered top edge (1/20 of pedestal height)
  const chamferGeo = new CylinderGeometry(1.1, 1.08, 0.04, 128, 4, false);
  geometries.push(chamferGeo);

  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.colorNode = uniform(new Color(0x16161d));
  chamferMat.roughnessNode = uniform(0.48);
  chamferMat.metalnessNode = uniform(0.62);

  const chamferMesh = new Mesh(chamferGeo, chamferMat);
  chamferMesh.position.y = -0.155;
  chamferMesh.castShadow = true;
  chamferMesh.receiveShadow = true;
  group.add(chamferMesh);
  materials.push(chamferMat);

  // ============================================================================
  // 4. CONTACT SHADOW (radial gradient plane, prominent)
  // ============================================================================
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  geometries.push(shadowGeo);

  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;

  // Radial gradient: dark center fading outward
  const shadowCanvas = document.createElement('canvas');
  shadowCanvas.width = 256;
  shadowCanvas.height = 256;
  const shadowCtx = shadowCanvas.getContext('2d');

  const radGrad = shadowCtx.createRadialGradient(128, 128, 0, 128, 128, 128);
  radGrad.addColorStop(0, 'rgba(0, 0, 0, 0.72)');
  radGrad.addColorStop(0.3, 'rgba(0, 0, 0, 0.4)');
  radGrad.addColorStop(0.65, 'rgba(0, 0, 0, 0.1)');
  radGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
  shadowCtx.fillStyle = radGrad;
  shadowCtx.fillRect(0, 0, shadowCanvas.width, shadowCanvas.height);

  const shadowTexture = new ctx.THREE.CanvasTexture(shadowCanvas);
  shadowTexture.needsUpdate = true;

  shadowMat.map = shadowTexture;
  textures.push(shadowTexture);

  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.365, 0.02);
  shadowMesh.scale.set(1.6, 1.6, 1);
  group.add(shadowMesh);
  materials.push(shadowMat);

  // ============================================================================
  // 5. LIGHTING (key + rim accent red + fill)
  // ============================================================================
  // Key light: strong directional at 40 degrees to catch brushed surface
  const keyLight = new ctx.THREE.DirectionalLight(0xf5f3ff, 1.35);
  keyLight.position.set(1.8, 2.0, 1.4);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 2048;
  keyLight.shadow.mapSize.height = 2048;
  keyLight.shadow.camera.near = 0.1;
  keyLight.shadow.camera.far = 12;
  keyLight.shadow.camera.left = -3.5;
  keyLight.shadow.camera.right = 3.5;
  keyLight.shadow.camera.top = 3.5;
  keyLight.shadow.camera.bottom = -3.5;
  keyLight.shadow.bias = -0.0008;
  group.add(keyLight);

  // Rim light: accent red (#ff2a38) from opposite side, strong to catch metal
  const rimLight = new ctx.THREE.DirectionalLight(0xff2a38, 1.15);
  rimLight.position.set(-1.8, 1.2, -1.6);
  group.add(rimLight);

  // Fill light: soft general illumination
  const fillLight = new ctx.THREE.DirectionalLight(0xe0e4f0, 0.45);
  fillLight.position.set(0.3, 0.9, 0.6);
  group.add(fillLight);

  // Back fill: subtle support from back-left
  const backLight = new ctx.THREE.DirectionalLight(0xa8b0c8, 0.25);
  backLight.position.set(-1.2, -0.5, -2.0);
  group.add(backLight);

  // ============================================================================
  // 6. TEXT CONTENT
  // ============================================================================
  // Headline: "Material study 03" (68px, 600 weight, centered, paper color)
  const headlineText = ctx.fontAtlas.createText('Material study 03', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -0.34  // negative tracking per spec
  });
  headlineText.position.set(0, -1.2, 0.1);
  group.add(headlineText);

  // Caption: "GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT" (18px, mono, uppercase with spacing)
  const captionText = ctx.fontAtlas.createText('GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.44  // 0.08em × 18px
  });
  captionText.position.set(0, -1.6, 0.1);
  group.add(captionText);

  // ============================================================================
  // 7. ORBIT ANIMATION (load trigger, speed 0.1 rad/s, radius 0.4)
  // ============================================================================
  const orbitResult = ctx.primitives['orbit'](group, {
    speed: 0.1,
    radius: 0.4
  });
  if (orbitResult && orbitResult.cleanup) {
    cleanups.push(orbitResult.cleanup);
  }

  // ============================================================================
  // 8. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    // Kill all timelines
    timelines.forEach(tl => tl && tl.kill());

    // Call all cleanup functions
    cleanups.forEach(fn => fn && fn());

    // Dispose materials
    materials.forEach(mat => mat && mat.dispose());

    // Dispose geometries
    geometries.forEach(geo => geo && geo.dispose());

    // Dispose textures
    textures.forEach(tex => tex && tex.dispose());
  };

  group.userData.handlers = {};

  return group;
}
